def _bounded_clocks(means, counts):
    from scipy.optimize import brentq

    def clocks(multiplier):
        return np.clip(means - multiplier / counts, -4.0, 4.0)
    offset = np.sum(means) / np.sum(1 / counts)
    c = means - offset / counts
    if np.max(np.abs(c)) <= 4.0:
        return c
    root = brentq(lambda t: np.sum(clocks(t)), np.min((means - 4.0) * counts), np.max((means + 4.0) * counts))
    return clocks(root)
